<?php $e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); ?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Beitrag – MeldeVerkehr</title><style>body{font-family:system-ui,sans-serif;background:#f5f7fa;color:#172033;margin:0}main{max-width:850px;margin:28px auto;padding:20px}.card{background:#fff;border:1px solid #dfe5ec;border-radius:15px;padding:20px;margin-bottom:14px}.comment{border-top:1px solid #e5e9ee;padding:12px 0}textarea{width:100%;box-sizing:border-box;padding:10px;border:1px solid #bac5d1;border-radius:8px}button{padding:9px 13px;border:0;border-radius:9px;background:#172033;color:#fff;font-weight:700;margin-top:8px}.muted{color:#66758a}</style></head><body><main><p><a href="/community">← Community</a></p><section class="card"><p><a href="/community/u/<?= rawurlencode($post['username']) ?>"><strong>@<?= $e($post['username']) ?></strong></a></p><h1><?= $e($post['topic']??'Beitrag') ?></h1><p><?= nl2br($e($post['body'])) ?></p><small class="muted"><?= $e($post['created_at']) ?></small><?php if($viewerUserId):?><form method="post" action="/community/posts/<?= rawurlencode($post['id']) ?>/helpful"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><button type="submit">Hilfreich</button></form><?php if($isFavorite):?><form method="post" action="/community/posts/<?= rawurlencode($post['id']) ?>/unfavorite"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><button type="submit">★ Favorit entfernen</button></form><?php else:?><form method="post" action="/community/posts/<?= rawurlencode($post['id']) ?>/favorite"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><button type="submit">☆ Als Favorit speichern</button></form><?php endif;?><?php endif;?></section>
<section class="card"><h2>Kommentare</h2><?php foreach($post['comments'] as $c):?><div class="comment"><strong>@<?= $e($c['username']) ?></strong><p><?= nl2br($e($c['body'])) ?></p></div><?php endforeach;?><?php if($viewerUserId):?><form method="post" action="/community/posts/<?= rawurlencode($post['id']) ?>/comments"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><textarea name="body" maxlength="4000" required></textarea><button type="submit">Kommentieren</button></form><?php endif;?></section>
</main></body></html>